FONT = "'Times New Roman', Times, 'Liberation Serif', serif"


def build() -> str:
    rows = "".join(
        f'<text x="{x0}" y="{y}" textLength="{x1 - x0}">{digits}</text>' for x0, x1, y, digits in ROWS
    )
    return (
        '<symbol id="em-figure" viewBox="0 0 350 332">'
        f'<g fill="var(--ink)" font-family="{FONT}" font-size="12">{rows}</g></symbol>'
        '<symbol id="em-scope" viewBox="0 0 350 332">'
        f'<path fill="var(--brand)" fill-rule="evenodd" d="{SCOPE}"/></symbol>'
    )


if __name__ == "__main__":
    print(build())
